-- Phase 3A: real walking-route distance (pgRouting over a campus footway
-- graph) + live delivery-location authorization (Realtime Broadcast).
--
-- See PHASE3_3A_ARCHITECTURE_REVISION.md for the full reasoning. Summary:
-- MapLibre GL JS (client-side, no key) renders a static, self-hosted
-- GeoJSON export of real OSM campus geometry (public/campus-map.geojson,
-- generated once via the Overpass API - the same public data source
-- already used for campus_points coordinates). Routing runs entirely
-- inside this database via pgRouting - no external routing API, no
-- recurring cost. Live location uses Supabase Realtime Broadcast,
-- authorized via RLS on realtime.messages (not persisted to any table).
--
-- Data provenance: the graph below (916 nodes / 1013 edges) is the real
-- pedestrian footway network from OpenStreetMap within a bounding box
-- around the known-real VIT Vellore campus points (12.9600,79.1480 to
-- 12.9820,79.1720), fetched live via the Overpass API on 2026-08-26.
-- Edge costs are haversine distances between real consecutive OSM way
-- vertices (typically a few meters apart), summed along a route - this is
-- real path-following distance, not a straight line between endpoints.
--
-- STATUS: prepared in the repo. Applied to STAGING only
-- (wemjskpbulebxgyhyhmk), never production (kjsseqlmnmiuqepfmldh).

-- ============ EXTENSIONS ============
-- Both confirmed available on Supabase (dashboard/SQL, no additional
-- cost - see PHASE3_3A_ARCHITECTURE_REVISION.md §4/§5). pgrouting depends
-- on postgis.
create extension if not exists postgis;
create extension if not exists pgrouting;

-- ============ ROUTING GRAPH ============
create table if not exists campus_path_nodes (
  id integer not null,
  lat double precision not null,
  lng double precision not null,
  constraint campus_path_nodes_pkey primary key (id)
);

create table if not exists campus_path_edges (
  id serial not null,
  source integer not null,
  target integer not null,
  cost double precision not null,
  reverse_cost double precision not null,
  constraint campus_path_edges_pkey primary key (id),
  constraint campus_path_edges_source_fkey foreign key (source) references campus_path_nodes(id),
  constraint campus_path_edges_target_fkey foreign key (target) references campus_path_nodes(id)
);

create index if not exists campus_path_edges_source_idx on campus_path_edges(source);
create index if not exists campus_path_edges_target_idx on campus_path_edges(target);

-- Reference data, same trust/access level as campus_points itself - see
-- 20260826100000_campus_points.sql's RLS rationale.
alter table campus_path_nodes enable row level security;
alter table campus_path_edges enable row level security;

drop policy if exists "campus_path_nodes_select_all" on campus_path_nodes;
create policy "campus_path_nodes_select_all"
  on campus_path_nodes for select
  using (true);

drop policy if exists "campus_path_edges_select_all" on campus_path_edges;
create policy "campus_path_edges_select_all"
  on campus_path_edges for select
  using (true);

-- Each campus_points row's nearest entry point into the walking-path graph
-- (nearest-node snapping, computed once from the OSM extract - not
-- recomputed live). Nullable: a point with no nearby path coverage yet
-- simply isn't routable, same honesty pattern as an unseeded coordinate -
-- compute_walking_route() falls back to haversine rather than failing.
do $$
begin
  alter table campus_points add column nearest_path_node_id integer references campus_path_nodes(id);
exception
  when duplicate_column then null;
end $$;

do $$
begin
  alter table campus_points add column nearest_path_node_distance_km double precision;
exception
  when duplicate_column then null;
end $$;

-- ============ campus_path_nodes / campus_path_edges DATA ============
-- Auto-generated node rows (id, lat, lng) from the OSM footway extract.

-- Auto-generated edge rows (source, target, cost_km, reverse_cost_km).
-- Footways are treated as bidirectional (reverse_cost = cost).

-- Snap each currently-seeded campus_points row to its nearest path node.
update campus_points set nearest_path_node_id = 315, nearest_path_node_distance_km = 0.053300 where key = 'one-food';
update campus_points set nearest_path_node_id = 664, nearest_path_node_distance_km = 0.028663 where key = 'campus-store';
update campus_points set nearest_path_node_id = 328, nearest_path_node_distance_km = 0.106546 where key = 'hostel-block-b';
update campus_points set nearest_path_node_id = 912, nearest_path_node_distance_km = 0.013648 where key = 'hostel-block-d';
update campus_points set nearest_path_node_id = 595, nearest_path_node_distance_km = 0.042935 where key = 'hostel-block-e';
update campus_points set nearest_path_node_id = 333, nearest_path_node_distance_km = 0.026606 where key = 'hostel-block-f';
update campus_points set nearest_path_node_id = 604, nearest_path_node_distance_km = 0.078797 where key = 'hostel-block-g';
update campus_points set nearest_path_node_id = 139, nearest_path_node_distance_km = 0.041970 where key = 'hostel-block-h';
update campus_points set nearest_path_node_id = 467, nearest_path_node_distance_km = 0.032738 where key = 'hostel-block-j';
update campus_points set nearest_path_node_id = 207, nearest_path_node_distance_km = 0.053921 where key = 'hostel-block-n';
update campus_points set nearest_path_node_id = 618, nearest_path_node_distance_km = 0.020534 where key = 'hostel-block-p';
update campus_points set nearest_path_node_id = 298, nearest_path_node_distance_km = 0.044661 where key = 'hostel-block-s';
update campus_points set nearest_path_node_id = 298, nearest_path_node_distance_km = 0.112112 where key = 'hostel-block-t';
-- ============ ROUTING RPC ============
-- Invoker rights (no SECURITY DEFINER), same reasoning as
-- compute_order_distance in 20260826110000_campus_points_3a_review.sql:
-- every table this reads (campus_points, campus_path_nodes,
-- campus_path_edges) is already readable by any authenticated caller via
-- its own RLS policy, so there's no privilege boundary to cross.
--
-- Falls back to straight-line haversine (never fails, never fabricates a
-- route) when either point isn't yet snapped into the path graph, or when
-- both points snap to the same nearest node (can happen when two points
-- are close together in an area with sparse path coverage) - a routed
-- distance of exactly the last-mile segments alone would be misleading in
-- that case, so it falls back to the direct-line calculation instead.
--
-- ETA is a simple estimate (distance / 5 km/h average walking pace), not
-- a measured value - labelled as such by callers, never presented as
-- exact.
create or replace function public.compute_walking_route(p_pickup_id uuid, p_delivery_id uuid)
returns table(distance_km double precision, geometry jsonb, eta_minutes double precision)
language plpgsql
set search_path = public
as $$
declare
  v_pickup campus_points%rowtype;
  v_delivery campus_points%rowtype;
  v_route_distance double precision;
  v_coords jsonb;
begin
  select * into v_pickup from campus_points where id = p_pickup_id and active;
  if not found then
    raise exception 'Unknown or inactive pickup point';
  end if;

  select * into v_delivery from campus_points where id = p_delivery_id and active;
  if not found then
    raise exception 'Unknown or inactive delivery point';
  end if;

  if v_pickup.nearest_path_node_id is null
     or v_delivery.nearest_path_node_id is null
     or v_pickup.nearest_path_node_id = v_delivery.nearest_path_node_id then
    distance_km := haversine_km(v_pickup.lat, v_pickup.lng, v_delivery.lat, v_delivery.lng);
    geometry := null;
    eta_minutes := round((distance_km / 5.0 * 60)::numeric, 1);
    return next;
    return;
  end if;

  select
    coalesce(sum(d.cost) filter (where d.edge <> -1), 0),
    jsonb_agg(jsonb_build_array(n.lng, n.lat) order by d.seq)
  into v_route_distance, v_coords
  from pgr_dijkstra(
    'select id, source, target, cost, reverse_cost from campus_path_edges',
    v_pickup.nearest_path_node_id,
    v_delivery.nearest_path_node_id,
    directed := true
  ) d
  join campus_path_nodes n on n.id = d.node;

  distance_km := v_route_distance + v_pickup.nearest_path_node_distance_km + v_delivery.nearest_path_node_distance_km;
  eta_minutes := round((distance_km / 5.0 * 60)::numeric, 1);
  geometry := jsonb_build_object('type', 'LineString', 'coordinates', coalesce(v_coords, '[]'::jsonb));
  return next;
end;
$$;

revoke all on function public.compute_walking_route(uuid, uuid) from public;
revoke execute on function public.compute_walking_route(uuid, uuid) from anon;
grant execute on function public.compute_walking_route(uuid, uuid) to authenticated;

-- ============ LIVE DELIVERY LOCATION: Realtime authorization ============
-- Broadcast-only, never persisted - see PHASE3_3A_ARCHITECTURE_REVISION.md
-- §3/§6. Nothing is written to any table; these policies govern who may
-- send/receive on the ephemeral channel topic `order-location-{orderId}`,
-- checked by Realtime against realtime.messages per Supabase's documented
-- Broadcast Authorization mechanism (RLS is enabled on that table by
-- Supabase by default - no ALTER TABLE needed here).
--
-- Both policies tie access directly to live order state (status in
-- picked_up/out_for_delivery), not just participant identity - so
-- authorization itself, not just client-side behaviour, cuts off the
-- moment an order is delivered or cancelled. No location visibility on
-- Home or to any student not requester/deliverer on this exact order.
drop policy if exists "requester_can_receive_delivery_location" on "realtime"."messages";
create policy "requester_can_receive_delivery_location"
  on "realtime"."messages"
  for select
  to authenticated
  using (
    realtime.messages.extension = 'broadcast'
    and exists (
      select 1 from orders
      where 'order-location-' || orders.id::text = realtime.topic()
        and orders.requester_id = (select auth.uid())
        and orders.status in ('picked_up', 'out_for_delivery')
    )
  );

drop policy if exists "deliverer_can_publish_delivery_location" on "realtime"."messages";
create policy "deliverer_can_publish_delivery_location"
  on "realtime"."messages"
  for insert
  to authenticated
  with check (
    realtime.messages.extension = 'broadcast'
    and exists (
      select 1 from orders
      where 'order-location-' || orders.id::text = realtime.topic()
        and orders.deliverer_id = (select auth.uid())
        and orders.status in ('picked_up', 'out_for_delivery')
    )
  );

